// Generate array of dates for last 30 days
const dates = [];
for (let i = 0; i < 30; i++) {
  const date = $now.minus(i, 'days').toFormat('yyyy-MM-dd');
  dates.push({
    PK: 'COST',
    SK: `DATE#${date}`,
    date: date
  });
}

return dates;

// This node collects all items after the loop
const items = $input.all();

// Filter out empty results and sort by date
const sortedData = items
  .filter(item => item.json.Item && item.json.Item.totalCost)
  .map(item => ({
    date: item.json.Item.date.S,
    cost: parseFloat(item.json.Item.totalCost.N)
  }))
  .sort((a, b) => new Date(a.date) - new Date(b.date));

if (sortedData.length === 0) {
  return {
    error: 'No data found for the last 30 days'
  };
}

// Calculate statistics
const totalCost = sortedData.reduce((sum, d) => sum + d.cost, 0);
const avgCost = totalCost / sortedData.length;
const minCost = Math.min(...sortedData.map(d => d.cost));
const maxCost = Math.max(...sortedData.map(d => d.cost));

// Create chart configuration for QuickChart
const chartConfig = {
  type: 'line',
  data: {
    labels: sortedData.map(d => d.date),
    datasets: [
      {
        label: 'Daily Cost ($)',
        data: sortedData.map(d => d.cost),
        borderColor: 'rgb(75, 192, 192)',
        backgroundColor: 'rgba(75, 192, 192, 0.2)',
        tension: 0.3,
        fill: true,
        pointRadius: 3,
        pointHoverRadius: 5
      }
    ]
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: 'Confluent Cloud - Last 30 Days Cost Trend',
        font: {
          size: 18
        }
      },
      legend: {
        display: true,
        position: 'top'
      }
    },
    scales: {
      y: {
        beginAtZero: true,
        title: {
          display: true,
          text: 'Cost (USD)'
        },
        ticks: {
          callback: function(value) {
            return '$' + value.toFixed(2);
          }
        }
      },
      x: {
        title: {
          display: true,
          text: 'Date'
        },
        ticks: {
          maxRotation: 45,
          minRotation: 45
        }
      }
    }
  }
};

const chartUrl = `https://quickchart.io/chart?width=1000&height=500&c=${encodeURIComponent(JSON.stringify(chartConfig))}`;

return {
  chartUrl: chartUrl,
  totalCost: totalCost.toFixed(2),
  avgCost: avgCost.toFixed(2),
  minCost: minCost.toFixed(2),
  maxCost: maxCost.toFixed(2),
  dataPoints: sortedData.length,
  startDate: sortedData[0].date,
  endDate: sortedData[sortedData.length - 1].date,
  data: sortedData
};
